const config = $input.first().json;
const daysBack = Number(config.DAYS_BACK) || 7;
const now = new Date();
const sinceDate = new Date(now.getTime() - (daysBack * 24 * 60 * 60 * 1000));

const formatDate = (d) => d.toISOString().split('T')[0];
const periodLabel = `${formatDate(sinceDate)} to ${formatDate(now)}`;

return [{
  json: {
    ...config,
    now_iso: now.toISOString(),
    since_iso: sinceDate.toISOString(),
    period_label: periodLabel,
    generated_at: now.toISOString()
  }
}];

const config = $('Calculate Date Range').first().json;
const sinceIso = config.since_iso;
const sinceTime = new Date(sinceIso).getTime();

// Helper to extract items array safely
function extractList(nodeName) {
  try {
    const items = $(nodeName).all();
    if (!items || items.length === 0) return [];
    if (items.length === 1 && Array.isArray(items[0].json)) {
      return items[0].json;
    }
    if (items.length === 1 && items[0].json && Array.isArray(items[0].json.data)) {
      return items[0].json.data;
    }
    if (items.length === 1 && items[0].json && items[0].json.message && items[0].json.documentation_url) {
      return [];
    }
    return items.map(i => i.json).filter(j => j && !j.message);
  } catch (e) {
    return [];
  }
}

const rawCommits = extractList('Fetch Commits');
const rawIssues = extractList('Fetch Closed Issues');
const rawPulls = extractList('Fetch Closed PRs');

// Process commits
const processedCommits = [];
const contributorMap = {};

for (const c of rawCommits) {
  if (!c || !c.commit) continue;
  const commitDate = c.commit?.author?.date || c.commit?.committer?.date;
  if (commitDate && new Date(commitDate).getTime() < sinceTime) continue;

  const authorName = c.author?.login || c.commit?.author?.name || 'Unknown';
  contributorMap[authorName] = (contributorMap[authorName] || 0) + 1;

  processedCommits.push({
    sha: (c.sha || '').substring(0, 7),
    message: (c.commit?.message || '').split('\n')[0].trim(),
    author: authorName,
    date: commitDate ? commitDate.split('T')[0] : ''
  });
}

// Process merged PRs
const mergedPRs = [];
for (const pr of rawPulls) {
  if (!pr || !pr.number) continue;
  if (!pr.merged_at) continue;
  if (new Date(pr.merged_at).getTime() < sinceTime) continue;

  const prAuthor = pr.user?.login || 'Unknown';
  contributorMap[prAuthor] = (contributorMap[prAuthor] || 0) + 1;

  mergedPRs.push({
    number: pr.number,
    title: pr.title || 'Untitled PR',
    author: prAuthor,
    merged_at: pr.merged_at.split('T')[0],
    url: pr.html_url || ''
  });
}

// Process closed issues (excluding PRs)
const closedIssues = [];
for (const iss of rawIssues) {
  if (!iss || !iss.number) continue;
  if (iss.pull_request) continue;
  if (!iss.closed_at) continue;
  if (new Date(iss.closed_at).getTime() < sinceTime) continue;

  const issAuthor = iss.user?.login || 'Unknown';
  contributorMap[issAuthor] = (contributorMap[issAuthor] || 0) + 1;

  const labels = (iss.labels || []).map(l => typeof l === 'string' ? l : l.name).filter(Boolean);

  closedIssues.push({
    number: iss.number,
    title: iss.title || 'Untitled Issue',
    author: issAuthor,
    closed_at: iss.closed_at.split('T')[0],
    labels: labels,
    url: iss.html_url || ''
  });
}

// Sort contributors by activity
const topContributors = Object.entries(contributorMap)
  .sort((a, b) => b[1] - a[1])
  .map(([handle, count]) => `@${handle} (${count} contributions)`);

const stats = {
  totalCommits: processedCommits.length,
  mergedPRs: mergedPRs.length,
  closedIssues: closedIssues.length,
  activeContributors: Object.keys(contributorMap).length
};

const isFrench = (config.LANGUAGE || 'EN').toUpperCase() === 'FR';

const systemPrompt = isFrench
  ? `Vous êtes un Lead Développeur et Release Engineer chevronné. Votre rôle est de rédiger un rapport hebdomadaire d'ingénierie (Weekly Dev Summary) clair, structuré, percutant et professionnel à partir des données d'activité Git et GitHub fournies.
Le rapport doit être rédigé en Français et comporter les sections suivantes :
1. 🎯 Résumé exécutif & Faits marquants de la semaine
2. 🚀 Nouvelles fonctionnalités & Améliorations majeures (Features)
3. 🐛 Corrections de bugs & Fiabilité (Fixes)
4. ⚠️ Changements majeurs & Ruptures de compatibilité (Breaking Changes - indiquer "Aucun" si absent)
5. 🔀 Pull Requests fusionnées & Tickets résolus
6. 🌟 Pleins feux sur les contributeurs (Contributor Spotlight)
7. 🧭 Cap pour la semaine prochaine & Perspectives

Adoptez un ton technique mais accessible aux chefs de projet et aux développeurs. Citez les numéros de PR et issues pertinents.`
  : `You are an elite Senior Staff Engineer and Release Manager. Your role is to generate a comprehensive, structured, and insightful Weekly Engineering Dev Summary based on Git commits and GitHub repository activity.
The summary must be written in English and structured into the following sections:
1. 🎯 Executive Summary & Weekly Highlights
2. 🚀 Features & Functional Enhancements
3. 🐛 Bug Fixes & Stability Improvements
4. ⚠️ Breaking Changes & Deprecations (explicitly state "None this week" if none)
5. 🔀 Merged Pull Requests & Closed Issues
6. 🌟 Contributor Spotlight & Top Collaborators
7. 🧭 Next Sprint Focus & Engineering Outlook

Adopt a polished, technically precise tone suitable for both technical leadership and engineering contributors. Reference relevant PR numbers (#XX) and commit details where appropriate.`;

const userPrompt = `Repository: ${config.GITHUB_OWNER}/${config.GITHUB_REPO}
Branch: ${config.GITHUB_BRANCH}
Time Window: ${config.period_label} (Past ${config.DAYS_BACK} days)

Activity Metrics:
- Total Commits: ${stats.totalCommits}
- Merged Pull Requests: ${stats.mergedPRs}
- Closed Issues: ${stats.closedIssues}
- Active Contributors: ${stats.activeContributors} (${topContributors.join(', ') || 'None'})

Raw Commits (${processedCommits.length}):
${processedCommits.length > 0 ? processedCommits.map(c => `- [${c.sha}] ${c.message} (by @${c.author} on ${c.date})`).join('\n') : 'No commits recorded in this window.'}

Merged Pull Requests (${mergedPRs.length}):
${mergedPRs.length > 0 ? mergedPRs.map(p => `- PR #${p.number}: ${p.title} (by @${p.author}, merged on ${p.merged_at})`).join('\n') : 'No pull requests merged in this window.'}

Closed Issues (${closedIssues.length}):
${closedIssues.length > 0 ? closedIssues.map(i => `- Issue #${i.number}: ${i.title} (labels: ${i.labels.join(', ') || 'none'}, author: @${i.author}, closed on ${i.closed_at})`).join('\n') : 'No issues closed in this window.'}

Please generate the complete weekly summary markdown following the required structure.`;

const apiKey = config.ANTHROPIC_API_KEY || $env.ANTHROPIC_API_KEY || '';
const model = config.CLAUDE_MODEL || 'claude-sonnet-4-20250514';

const claudePayload = {
  model: model,
  max_tokens: 4096,
  temperature: 0.2,
  system: systemPrompt,
  messages: [
    {
      role: "user",
      content: userPrompt
    }
  ]
};

return [{
  json: {
    ...config,
    stats,
    topContributors,
    processedCommits,
    mergedPRs,
    closedIssues,
    apiKey,
    model,
    claudePayload
  }
}];

const inputData = $input.first().json;
const prevData = $('Aggregate & Build Claude Prompt').first().json;

let narrativeText = "";
if (inputData.content && Array.isArray(inputData.content) && inputData.content[0] && inputData.content[0].text) {
  narrativeText = inputData.content[0].text;
} else if (inputData.error) {
  narrativeText = `> ⚠️ **Claude API Response Notice:** ${inputData.error.message || JSON.stringify(inputData.error)}`;
} else {
  narrativeText = "Weekly summary could not be retrieved from Claude API.";
}

const repo = `${prevData.GITHUB_OWNER}/${prevData.GITHUB_REPO}`;
const period = prevData.period_label;
const stats = prevData.stats;
const isFrench = (prevData.LANGUAGE || 'EN').toUpperCase() === 'FR';

const headerTitle = isFrench 
  ? `# 📊 Synthèse Hebdomadaire Dev : ${repo}`
  : `# 📊 Weekly Engineering Summary: ${repo}`;

const periodLabel = isFrench ? 'Période' : 'Period';
const commitsLabel = isFrench ? 'Commits' : 'Commits';
const prsLabel = isFrench ? 'PRs fusionnées' : 'Merged PRs';
const issuesLabel = isFrench ? 'Tickets résolus' : 'Closed Issues';
const contribLabel = isFrench ? 'Contributeurs actifs' : 'Active Contributors';
const generatedLabel = isFrench ? 'Généré par Claude Code via n8n' : 'Generated by Claude Code via n8n';

const fullMarkdown = `${headerTitle}

| 📅 ${periodLabel} | 🔨 ${commitsLabel} | 🔀 ${prsLabel} | 🎯 ${issuesLabel} | 👥 ${contribLabel} |
| :---: | :---: | :---: | :---: | :---: |
| **${period}** | **${stats.totalCommits}** | **${stats.mergedPRs}** | **${stats.closedIssues}** | **${stats.activeContributors}** |

> *${generatedLabel} | Model: \`${prevData.model}\` | Date: ${new Date().toISOString().split('T')[0]}*

---

${narrativeText}
`;

// Prepare Discord Embed Payload
const discordDescription = narrativeText.length > 3900 
  ? narrativeText.substring(0, 3900) + '...\n\n*(Full report truncated for Discord embed limit)*'
  : narrativeText;

const discordPayload = {
  username: "Claude Code Dev Digest",
  avatar_url: "https://upload.wikimedia.org/wikipedia/commons/7/70/Claude_AI_symbol.svg",
  content: `🚀 **Weekly Dev Summary for \`${repo}\` (${period})**`,
  embeds: [
    {
      title: `📊 ${repo} Dev Digest`,
      description: discordDescription,
      color: 5793266,
      fields: [
        { name: "🔨 Commits", value: `${stats.totalCommits}`, inline: true },
        { name: "🔀 Merged PRs", value: `${stats.mergedPRs}`, inline: true },
        { name: "🎯 Closed Issues", value: `${stats.closedIssues}`, inline: true },
        { name: "👥 Contributors", value: `${stats.activeContributors}`, inline: true },
        { name: "📅 Period", value: period, inline: true }
      ],
      footer: {
        text: `Automated by n8n + Claude Code (${prevData.model})`
      },
      timestamp: new Date().toISOString()
    }
  ]
};

// Prepare Slack Block Kit Payload
const slackText = narrativeText.length > 2900 
  ? narrativeText.substring(0, 2900) + '...\n\n_(Report truncated for Slack block limit)_'
  : narrativeText;

const slackPayload = {
  text: `Weekly Dev Summary: ${repo} (${period})`,
  blocks: [
    {
      type: "header",
      text: {
        type: "plain_text",
        text: `📊 Weekly Engineering Digest: ${repo}`,
        emoji: true
      }
    },
    {
      type: "section",
      fields: [
        { type: "mrkdwn", text: `*📅 Period:*\n${period}` },
        { type: "mrkdwn", text: `*🔨 Commits:*\n${stats.totalCommits}` },
        { type: "mrkdwn", text: `*🔀 Merged PRs:*\n${stats.mergedPRs}` },
        { type: "mrkdwn", text: `*🎯 Closed Issues:*\n${stats.closedIssues}` }
      ]
    },
    { type: "divider" },
    {
      type: "section",
      text: {
        type: "mrkdwn",
        text: slackText
      }
    },
    { type: "divider" },
    {
      type: "context",
      elements: [
        {
          type: "mrkdwn",
          text: `Generated by *Claude Code* (\`${prevData.model}\`) via n8n • ${new Date().toISOString()}`
        }
      ]
    }
  ]
};

// Prepare Generic Webhook Payload
const webhookPayload = {
  event: "weekly_dev_summary",
  repository: repo,
  period: period,
  stats: stats,
  model: prevData.model,
  markdown: fullMarkdown,
  narrative: narrativeText,
  generated_at: new Date().toISOString()
};

// Prepare Email Payload
const emailSubject = `[Weekly Dev Digest] ${repo} - ${period}`;
const emailHtml = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; line-height: 1.6; color: #1f2937; background: #f9fafb; padding: 20px; }
    .container { max-width: 800px; margin: 0 auto; background: #ffffff; border-radius: 8px; border: 1px solid #e5e7eb; overflow: hidden; }
    .header { background: #4f46e5; color: #ffffff; padding: 24px; text-align: center; }
    .header h1 { margin: 0 0 8px 0; font-size: 24px; }
    .stats { display: flex; justify-content: space-around; background: #f3f4f6; padding: 16px; border-bottom: 1px solid #e5e7eb; text-align: center; }
    .stat-box { flex: 1; }
    .stat-val { font-size: 20px; font-weight: bold; color: #4f46e5; }
    .stat-label { font-size: 12px; color: #6b7280; text-transform: uppercase; }
    .content { padding: 28px; white-space: pre-wrap; font-family: inherit; }
    .footer { background: #f9fafb; padding: 16px; text-align: center; font-size: 12px; color: #9ca3af; border-top: 1px solid #e5e7eb; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>📊 Weekly Engineering Digest</h1>
      <p style="margin:0; opacity: 0.9;">${repo} &bull; ${period}</p>
    </div>
    <div class="stats">
      <div class="stat-box"><div class="stat-val">${stats.totalCommits}</div><div class="stat-label">Commits</div></div>
      <div class="stat-box"><div class="stat-val">${stats.mergedPRs}</div><div class="stat-label">Merged PRs</div></div>
      <div class="stat-box"><div class="stat-val">${stats.closedIssues}</div><div class="stat-label">Closed Issues</div></div>
      <div class="stat-box"><div class="stat-val">${stats.activeContributors}</div><div class="stat-label">Contributors</div></div>
    </div>
    <div class="content">
${narrativeText.replace(/</g, '&lt;').replace(/>/g, '&gt;')}
    </div>
    <div class="footer">
      Generated automatically by Claude Code (${prevData.model}) via n8n &bull; ${new Date().toUTCString()}
    </div>
  </div>
</body>
</html>`;

return [{
  json: {
    ...prevData,
    markdown_report: fullMarkdown,
    narrative_summary: narrativeText,
    discord_payload: discordPayload,
    slack_payload: slackPayload,
    webhook_payload: webhookPayload,
    email_payload: {
      to: prevData.NOTIFICATION_EMAIL || '',
      subject: emailSubject,
      html: emailHtml,
      text: fullMarkdown
    }
  }
}];

const data = $input.first().json;
const target = (data.NOTIFICATION_TARGET || 'all').toLowerCase();
const outputs = [];

const discordUrl = data.DISCORD_WEBHOOK_URL || $env.DISCORD_WEBHOOK_URL || '';
const slackUrl = data.SLACK_WEBHOOK_URL || $env.SLACK_WEBHOOK_URL || '';
const customUrl = data.CUSTOM_WEBHOOK_URL || $env.CUSTOM_WEBHOOK_URL || '';
const emailTo = data.NOTIFICATION_EMAIL || $env.NOTIFICATION_EMAIL || '';

const shouldSendDiscord = (target === 'all' || target === 'discord') && discordUrl;
const shouldSendSlack = (target === 'all' || target === 'slack') && slackUrl;
const shouldSendWebhook = (target === 'all' || target === 'webhook') && customUrl;
const shouldSendEmail = (target === 'all' || target === 'email') && emailTo;

if (shouldSendDiscord) {
  outputs.push({
    json: {
      channel: 'discord',
      url: discordUrl,
      payload: data.discord_payload,
      markdown: data.markdown_report
    }
  });
}

if (shouldSendSlack) {
  outputs.push({
    json: {
      channel: 'slack',
      url: slackUrl,
      payload: data.slack_payload,
      markdown: data.markdown_report
    }
  });
}

if (shouldSendWebhook) {
  outputs.push({
    json: {
      channel: 'webhook',
      url: customUrl,
      payload: data.webhook_payload,
      markdown: data.markdown_report
    }
  });
}

if (shouldSendEmail) {
  outputs.push({
    json: {
      channel: 'email',
      email: data.email_payload,
      markdown: data.markdown_report
    }
  });
}

if (outputs.length === 0) {
  outputs.push({
    json: {
      channel: 'dry_run',
      notice: 'No webhook or email target configured. Dev summary generated successfully.',
      markdown: data.markdown_report
    }
  });
}

return outputs;

const item = $input.first().json;
const email = item.email || {};

return [{
  json: {
    status: 'email_dispatched',
    recipient: email.to || 'configured_recipient',
    subject: email.subject || 'Weekly Dev Summary',
    preview: email.text ? email.text.substring(0, 200) + '...' : '',
    timestamp: new Date().toISOString()
  }
}];
